package rocks.pkb.plektra.core.suggestions

import android.content.res.AssetManager
import java.io.InputStream
import java.util.Locale
import java.util.concurrent.ConcurrentHashMap
import org.json.JSONObject

/**
 * Plektra Custom: per-language tweaks applied on top of a bundled base dictionary.
 *
 * For English this switches the dictionary to British spelling: US-only spellings are removed
 * (so "color" is treated as unknown and can be auto-corrected to "colour"), British forms take
 * over their frequency, and a few everyday British words are added. Generated by
 * tools/british_english/build_en_gb_assets.py.
 */
data class LanguageOverlay(
    val removals: Set<String>,
    val frequencies: Map<String, Int>
) {
    companion object {
        fun assetPathFor(locale: Locale): String? = when (locale.language.lowercase(Locale.ROOT)) {
            "en" -> "common/dictionaries/en_gb_overlay.tsv"
            else -> null
        }

        /** Extra exact auto-corrections merged into the bundled list for [languageCode]. */
        fun correctionsAssetPathFor(languageCode: String): String? = when (languageCode.lowercase(Locale.ROOT)) {
            "en" -> "common/autocorrect/en_gb_spelling.json"
            else -> null
        }

        private val spellingCache = ConcurrentHashMap<String, Map<String, String>>()

        /**
         * Preferred (British) spelling for a fully typed word, e.g. "color" -> "colour", or null.
         * Keeps the typed capitalisation. Loads the small JSON map once per language.
         */
        fun preferredSpelling(assets: AssetManager, locale: Locale, typed: String): String? {
            val path = correctionsAssetPathFor(locale.language) ?: return null
            val map = spellingCache.getOrPut(path) {
                try {
                    val json = JSONObject(assets.open(path).bufferedReader().use { it.readText() })
                    buildMap { json.keys().forEach { key -> put(key, json.getString(key)) } }
                } catch (_: Exception) {
                    emptyMap()
                }
            }
            val variant = map[typed.lowercase(Locale.ROOT)] ?: return null
            return CasingHelper.applyCasing(variant, typed)
        }

        fun load(assets: AssetManager, locale: Locale): LanguageOverlay? {
            val path = assetPathFor(locale) ?: return null
            return try {
                assets.open(path).use { parse(it) }
            } catch (_: Exception) {
                null
            }
        }

        fun parse(input: InputStream): LanguageOverlay {
            val removals = HashSet<String>()
            val frequencies = HashMap<String, Int>()
            input.bufferedReader(Charsets.UTF_8).forEachLine { raw ->
                if (raw.isBlank() || raw.startsWith("#")) return@forEachLine
                val parts = raw.split('\t')
                when (parts[0]) {
                    "remove" -> parts.getOrNull(1)?.takeIf { it.isNotBlank() }?.let { removals.add(it) }
                    "set" -> {
                        val word = parts.getOrNull(1)?.takeIf { it.isNotBlank() } ?: return@forEachLine
                        val frequency = parts.getOrNull(2)?.toIntOrNull() ?: return@forEachLine
                        frequencies[word] = frequency.coerceIn(1, 255)
                    }
                }
            }
            return LanguageOverlay(removals, frequencies)
        }
    }
}
